Compute the maximum over all non-empty contiguous windows with nested loops.

```python
def pre(xs):
    if len(xs) < 1 or len(xs) > 6:
        return False
    for x in xs:
        if x < -10 or x > 10:
            return False
    return True


def post(xs, result):
    n = len(xs)
    best = xs[0]
    for i in range(n):
        s = 0
        for j in range(i, n):
            s = s + xs[j]
            if s > best:
                best = s
    return result == best
```
